//	    FromName:     "Memos Notifications",
//	    UseTLS:       true,
//	}
//
// # Common SMTP Settings
//
// Gmail (requires App Password):
//   - Host: smtp.gmail.com
//   - Port: 587 (TLS) or 465 (SSL)
//   - Username: your-email@gmail.com
//   - UseTLS: true (for port 587) or UseSSL: true (for port 465)
//
// SendGrid:
